"""HTTP client for ``dtc``."""

from __future__ import annotations

import os
import uuid
from typing import Any

import httpx

from dtc_cli.config import ConfigError, resolve_credentials


class APIError(RuntimeError):
    """HTTP or API error returned by the management server."""


def _is_cloudfront_block(response: httpx.Response) -> bool:
    if response.status_code != 403:
        return False
    server = response.headers.get("server", "").lower()
    via = response.headers.get("via", "").lower()
    return (
        "cloudfront" in server or "cloudfront" in via or "Generated by cloudfront" in response.text
    )


def _make_http_client(
    base_url: str, token: str, *, timeout: float, force_ipv4: bool
) -> httpx.Client:
    transport = httpx.HTTPTransport(local_address="0.0.0.0") if force_ipv4 else None
    return httpx.Client(
        base_url=base_url,
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
        },
        timeout=timeout,
        follow_redirects=False,
        transport=transport,
    )


class DtcClient:
    def __init__(self, base_url: str, token: str, *, timeout: float = 30.0) -> None:
        self.base_url = base_url.rstrip("/")
        self.token = token
        self._timeout = timeout
        self._force_ipv4 = os.environ.get("DTC_FORCE_IPV4", "").strip().lower() in {
            "1",
            "true",
            "yes",
        }
        self._http = _make_http_client(
            self.base_url,
            self.token,
            timeout=timeout,
            force_ipv4=self._force_ipv4,
        )

    def _request(self, method: str, path: str, **kwargs: Any) -> dict[str, Any]:
        response = self._http.request(method, path, **kwargs)
        if not self._force_ipv4 and _is_cloudfront_block(response):
            # Retry once over IPv4: some hosts have IPv6 blocked by edge WAF while IPv4 succeeds.
            self._force_ipv4 = True
            self._http.close()
            self._http = _make_http_client(
                self.base_url,
                self.token,
                timeout=self._timeout,
                force_ipv4=True,
            )
            response = self._http.request(method, path, **kwargs)
        return self._handle(response)

    def _handle(self, response: httpx.Response) -> dict[str, Any]:
        if response.status_code >= 400:
            try:
                body = response.json()
            except ValueError:
                body = None
            if isinstance(body, dict):
                err = body.get("error")
                if isinstance(err, dict):
                    code = err.get("code", response.status_code)
                    message = err.get("message", response.text)
                    req_id = err.get("request_id") or ""
                    suffix = f" [request_id={req_id}]" if req_id else ""
                    raise APIError(f"{code}: {message}{suffix}")
                if isinstance(err, str):
                    raise APIError(f"{err}: {body.get('message', response.text)}")
            if _is_cloudfront_block(response):
                cf_id = response.headers.get("x-amz-cf-id", "")
                suffix = f" (cf_id={cf_id})" if cf_id else ""
                raise APIError(
                    f"HTTP 403 (CloudFront/WAF blocked request{suffix}): "
                    "check request body size (edge WAF caps single bodies at 8 KB) "
                    "or IPv4/IPv6 routing."
                )
            raise APIError(f"HTTP {response.status_code}: {response.text[:300]}")
        try:
            data = response.json()
        except ValueError as exc:
            raise APIError(f"Invalid JSON response from server: {exc}") from exc
        if not isinstance(data, dict):
            return {"data": data}
        return data

    def get(self, path: str, *, params: dict[str, Any] | None = None) -> dict[str, Any]:
        return self._request("GET", path, params=params)

    def post(
        self,
        path: str,
        *,
        json_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
        extra_headers: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        headers = {"Idempotency-Key": idempotency_key or str(uuid.uuid4())}
        if extra_headers:
            headers.update(extra_headers)
        return self._request("POST", path, json=json_body or {}, headers=headers)

    def patch(
        self,
        path: str,
        *,
        json_body: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        headers = {"Idempotency-Key": idempotency_key or str(uuid.uuid4())}
        return self._request("PATCH", path, json=json_body or {}, headers=headers)


def get_client(url: str | None = None, token: str | None = None) -> DtcClient:
    try:
        base, secret = resolve_credentials(url=url, token=token)
    except ConfigError as exc:
        raise APIError(str(exc)) from exc
    return DtcClient(base, secret)
